import importlib.util,json
from pathlib import Path
root=Path.cwd()
spec=importlib.util.spec_from_file_location('dag_profile',root/'tools/eunoia-profile/run.py')
p=importlib.util.module_from_spec(spec);spec.loader.exec_module(p)
for case in json.loads((root/'benchmarks/eunoia/cases.json').read_text()):
 if case['id']in('lia_disjunctive_bounds','lia_inconsistent_bounds'):
  p.CASES[case['id']]=(case['statement'],'cvc5_eunoia')
p.CASES['control_uf']=(p.CASES['congruence'][0],'verit')
p.CASES['control_lia']=(p.CASES['lia_disjunctive_bounds'][0],'verit')
for case in json.loads((root/'benchmarks/eunoia/model-graph.json').read_text()):
 if case['id']=='uf_nested_40':p.CASES[case['id']]=(case['statement'],'cvc5_eunoia')
p.CASES['control_uf40']=(p.CASES['uf_nested_40'][0],'verit')
p.CASES['control_lia_inconsistent']=(p.CASES['lia_inconsistent_bounds'][0],'verit')
import hashlib,os
snapshot=os.environ.get('EUNOIA_LIBRARY_SNAPSHOT')
default=root/'_build/default'
original_loadpath=p.loadpath
if snapshot:
 p.loadpath=lambda:[x.replace(str(default),snapshot)for x in original_loadpath()]
original_execute=p.execute
def execute(command,directory,timeout):
 if any(str(x).endswith('audit-eunoia-assumptions.py')for x in command):
  command=command+['--build-loadpaths']
  flags=p.loadpath()
  for i in range(0,len(flags),3):command+=['--loadpath',flags[i+1],flags[i+2]]
 return original_execute(command,directory,timeout)
p.execute=execute
original_write=p.write_json
def write_json(path,value):
 if path.name=='metadata.json':
  manifest=json.loads((root/'_build/eunoia-baseline-before-opaque/manifest.json').read_text())
  base=Path(snapshot)if snapshot else default
  value['array_comparison']={'variant':'reference'if snapshot else'opaque-proof',
   'PArray_source_sha256':manifest['PArray_source_sha256']if snapshot else hashlib.sha256((root/'theories/utils/PArray.v').read_bytes()).hexdigest(),
   'library_root':str(base),'vo_sha256':{rel:hashlib.sha256((base/rel).read_bytes()).hexdigest()for rel in manifest['vo_sha256']}}
 return original_write(path,value)
p.write_json=write_json
raise SystemExit(p.main())
